def total_after_discount(amount, vip=False):
    rate = 0.2 if vip else 0.05
    return amount * rate - (10 if amount >= 200 else 0)

fixtures.tests/test_pricing.py:
import unittest
from src.pricing import total_after_discount

class PricingTests(unittest.TestCase):
    def test_regular(self):
        self.assertAlmostEqual(total_after_discount(100), 95)
    def test_vip(self):
        self.assertAlmostEqual(total_after_discount(100, True), 80)
    def test_threshold(self):
        self.assertAlmostEqual(total_after_discount(200), 180)
    def test_vip_threshold(self):
        self.assertAlmostEqual(total_after_discount(200, True), 150)
    def test_zero(self):
        self.assertEqual(total_after_discount(0), 0)
